template:
# =========================================
# Station metadata
# =========================================

# HELP weewx_station_info Static station metadata
# TYPE weewx_station_info gauge
weewx_station_info{location="$station.location",latitude="$station.stn_info.latitude_f",longitude="$station.stn_info.longitude_f",altitude_m="$station.altitude.meter.raw",link="$station.station_url"} 1


# =========================================
# Generation metadata
# =========================================

# HELP weewx_generation_info WeeWX generator and generation time
# TYPE weewx_generation_info gauge
weewx_generation_info{generator="weewx $station.version",time="$current.dateTime.format('%Y-%m-%dT%H:%M:%S%z')"} 1

# =========================================
# Current conditions (gauges)
# =========================================

#set $c = $current if $current else None

# HELP weewx_temperature Current outdoor temperature
# TYPE weewx_temperature gauge
weewx_temperature{units="${$c.outTemp.format(' ').lstrip() if $c and $c.outTemp else 'unknown'}"} ${$c.outTemp.raw if $c and $c.outTemp and $c.outTemp.raw is not None else 'NaN'}

# HELP weewx_dewpoint Current dewpoint
# TYPE weewx_dewpoint gauge
weewx_dewpoint{units="${$c.dewpoint.format(' ').lstrip() if $c and $c.dewpoint else 'unknown'}"} ${$c.dewpoint.raw if $c and $c.dewpoint and $c.dewpoint.raw is not None else 'NaN'}

# HELP weewx_humidity Current outdoor humidity
# TYPE weewx_humidity gauge
weewx_humidity{units="${$c.outHumidity.format(' ').lstrip() if $c and $c.outHumidity else 'unknown'}"} ${$c.outHumidity.raw if $c and $c.outHumidity and $c.outHumidity.raw is not None else 'NaN'}

# HELP weewx_heat_index Current heat index
# TYPE weewx_heat_index gauge
weewx_heat_index{units="${$c.heatindex.format(' ').lstrip() if $c and $c.heatindex else 'unknown'}"} ${$c.heatindex.raw if $c and $c.heatindex and $c.heatindex.raw is not None else 'NaN'}

# HELP weewx_barometer Current barometric pressure
# TYPE weewx_barometer gauge
weewx_barometer{units="${$c.barometer.format(' ').lstrip() if $c and $c.barometer else 'unknown'}"} ${$c.barometer.raw if $c and $c.barometer and $c.barometer.raw is not None else 'NaN'}

# HELP weewx_wind_speed Current wind speed
# TYPE weewx_wind_speed gauge
weewx_wind_speed{units="${$c.windSpeed.format(' ').lstrip() if $c and $c.windSpeed else 'unknown'}"} ${$c.windSpeed.raw if $c and $c.windSpeed and $c.windSpeed.raw is not None else 'NaN'}

# HELP weewx_wind_gust Current wind gust
# TYPE weewx_wind_gust gauge
weewx_wind_gust{units="${$c.windGust.format(' ').lstrip() if $c and $c.windGust else 'unknown'}"} ${$c.windGust.raw if $c and $c.windGust and $c.windGust.raw is not None else 'NaN'}

# HELP weewx_wind_direction Current wind direction
# TYPE weewx_wind_direction gauge
weewx_wind_direction{units="${$c.windDir.format(' ').lstrip() if $c and $c.windDir else 'unknown'}"} ${$c.windDir.raw if $c and $c.windDir and $c.windDir.raw is not None else 'NaN'}

# HELP weewx_wind_chill Current wind chill
# TYPE weewx_wind_chill gauge
weewx_wind_chill{units="${$c.windchill.format(' ').lstrip() if $c and $c.windchill else 'unknown'}"} ${$c.windchill.raw if $c and $c.windchill and $c.windchill.raw is not None else 'NaN'}

# HELP weewx_rain_rate Current rain rate
# TYPE weewx_rain_rate gauge
weewx_rain_rate{units="${$c.rainRate.format(' ').lstrip() if $c and $c.rainRate else 'unknown'}"} ${$c.rainRate.raw if $c and $c.rainRate and $c.rainRate.raw is not None else 'NaN'}

# HELP weewx_inside_temperature Current indoor temperature
# TYPE weewx_inside_temperature gauge
weewx_inside_temperature{units="${$c.inTemp.format(' ').lstrip() if $c and $c.inTemp else 'unknown'}"} ${$c.inTemp.raw if $c and $c.inTemp and $c.inTemp.raw is not None else 'NaN'}

# HELP weewx_inside_humidity Current indoor humidity
# TYPE weewx_inside_humidity gauge
weewx_inside_humidity{units="${$c.inHumidity.format(' ').lstrip() if $c and $c.inHumidity else 'unknown'}"} ${$c.inHumidity.raw if $c and $c.inHumidity and $c.inHumidity.raw is not None else 'NaN'}

# =========================================
# Aggregate helpers
# period = day | week | month | year
# =========================================

#set $d = $day if $day else None
#set $w = $week if $week else None
#set $m = $month if $month else None
#set $y = $year if $year else None

# ---------- Temperature ----------

# HELP weewx_temperature_max Maximum temperature
# TYPE weewx_temperature_max gauge
weewx_temperature_max{period="day",units="${$d.outTemp.max.format(' ').lstrip() if $d and $d.outTemp and $d.outTemp.max else 'unknown'}"} ${$d.outTemp.max.raw if $d and $d.outTemp and $d.outTemp.max and $d.outTemp.max.raw is not None else 'NaN'}
weewx_temperature_max{period="week",units="${$w.outTemp.max.format(' ').lstrip() if $w and $w.outTemp and $w.outTemp.max else 'unknown'}"} ${$w.outTemp.max.raw if $w and $w.outTemp and $w.outTemp.max and $w.outTemp.max.raw is not None else 'NaN'}
weewx_temperature_max{period="month",units="${$m.outTemp.max.format(' ').lstrip() if $m and $m.outTemp and $m.outTemp.max else 'unknown'}"} ${$m.outTemp.max.raw if $m and $m.outTemp and $m.outTemp.max and $m.outTemp.max.raw is not None else 'NaN'}
weewx_temperature_max{period="year",units="${$y.outTemp.max.format(' ').lstrip() if $y and $y.outTemp and $y.outTemp.max else 'unknown'}"} ${$y.outTemp.max.raw if $y and $y.outTemp and $y.outTemp.max and $y.outTemp.max.raw is not None else 'NaN'}

# HELP weewx_temperature_min Minimum temperature
# TYPE weewx_temperature_min gauge
weewx_temperature_min{period="day",units="${$d.outTemp.min.format(' ').lstrip() if $d and $d.outTemp and $d.outTemp.min else 'unknown'}"} ${$d.outTemp.min.raw if $d and $d.outTemp and $d.outTemp.min and $d.outTemp.min.raw is not None else 'NaN'}
weewx_temperature_min{period="week",units="${$w.outTemp.min.format(' ').lstrip() if $w and $w.outTemp and $w.outTemp.min else 'unknown'}"} ${$w.outTemp.min.raw if $w and $w.outTemp and $w.outTemp.min and $w.outTemp.min.raw is not None else 'NaN'}
weewx_temperature_min{period="month",units="${$m.outTemp.min.format(' ').lstrip() if $m and $m.outTemp and $m.outTemp.min else 'unknown'}"} ${$m.outTemp.min.raw if $m and $m.outTemp and $m.outTemp.min and $m.outTemp.min.raw is not None else 'NaN'}
weewx_temperature_min{period="year",units="${$y.outTemp.min.format(' ').lstrip() if $y and $y.outTemp and $y.outTemp.min else 'unknown'}"} ${$y.outTemp.min.raw if $y and $y.outTemp and $y.outTemp.min and $y.outTemp.min.raw is not None else 'NaN'}

