weewx_dewpoint_max{period="week"} ${$w.dewpoint.max.raw if $w and $w.dewpoint and $w.dewpoint.max and $w.dewpoint.max.raw is not None else 'NaN'}
weewx_dewpoint_max{period="month"} ${$m.dewpoint.max.raw if $m and $m.dewpoint and $m.dewpoint.max and $m.dewpoint.max.raw is not None else 'NaN'}
weewx_dewpoint_max{period="year"} ${$y.dewpoint.max.raw if $y and $y.dewpoint and $y.dewpoint.max and $y.dewpoint.max.raw is not None else 'NaN'}

# HELP weewx_dewpoint_min Minimum dewpoint
