weewx_dewpoint_min{period="week"} ${$w.dewpoint.min.raw if $w and $w.dewpoint and $w.dewpoint.min and $w.dewpoint.min.raw is not None else 'NaN'}
weewx_dewpoint_min{period="month"} ${$m.dewpoint.min.raw if $m and $m.dewpoint and $m.dewpoint.min and $m.dewpoint.min.raw is not None else 'NaN'}
weewx_dewpoint_min{period="year"} ${$y.dewpoint.min.raw if $y and $y.dewpoint and $y.dewpoint.min and $y.dewpoint.min.raw is not None else 'NaN'}

# ---------- Humidity ----------

# HELP weewx_humidity_max Maximum humidity
# TYPE weewx_humidity_max gauge
