weewx_humidity_max{period="week"} ${$w.outHumidity.max.raw if $w and $w.outHumidity and $w.outHumidity.max and $w.outHumidity.max.raw is not None else 'NaN'}
weewx_humidity_max{period="month"} ${$m.outHumidity.max.raw if $m and $m.outHumidity and $m.outHumidity.max and $m.outHumidity.max.raw is not None else 'NaN'}
weewx_humidity_max{period="year"} ${$y.outHumidity.max.raw if $y and $y.outHumidity and $y.outHumidity.max and $y.outHumidity.max.raw is not None else 'NaN'}

# HELP weewx_humidity_min Minimum humidity
# TYPE weewx_humidity_min gauge
weewx_humidity_min{period="day"} ${$d.outHumidity.min.raw if $d and $d.outHumidity and $d.outHumidity.min and $d.outHumidity.min.raw is not None else 'NaN'}
weewx_humidity_min{period="week"} ${$w.outHumidity.min.raw if $w and $w.outHumidity and $w.outHumidity.min and $w.outHumidity.min.raw is not None else 'NaN'}
weewx_humidity_min{period="month"} ${$m.outHumidity.min.raw if $m and $m.outHumidity and $m.outHumidity.min and $m.outHumidity.min.raw is not None else 'NaN'}
