weewx_barometer_max{period="week"} ${$w.barometer.max.raw if $w and $w.barometer and $w.barometer.max and $w.barometer.max.raw is not None else 'NaN'}
weewx_barometer_max{period="month"} ${$m.barometer.max.raw if $m and $m.barometer and $m.barometer.max and $m.barometer.max.raw is not None else 'NaN'}
