weewx_barometer_min{period="week"} ${$w.barometer.min.raw if $w and $w.barometer and $w.barometer.min and $w.barometer.min.raw is not None else 'NaN'}
weewx_barometer_min{period="month"} ${$m.barometer.min.raw if $m and $m.barometer and $m.barometer.min and $m.barometer.min.raw is not None else 'NaN'}
