weewx_wind_speed_max{period="week"} ${$w.windSpeed.max.raw if $w and $w.windSpeed and $w.windSpeed.max and $w.windSpeed.max.raw is not None else 'NaN'}
weewx_wind_speed_max{period="month"} ${$m.windSpeed.max.raw if $m and $m.windSpeed and $m.windSpeed.max and $m.windSpeed.max.raw is not None else 'NaN'}
weewx_wind_speed_max{period="year"} ${$y.windSpeed.max.raw if $y and $y.windSpeed and $y.windSpeed.max and $y.windSpeed.max.raw is not None else 'NaN'}

# HELP weewx_wind_gust_max Maximum wind gust
# TYPE weewx_wind_gust_max gauge
weewx_wind_gust_max{period="day"} ${$d.windGust.max.raw if $d and $d.windGust and $d.windGust.max and $d.windGust.max.raw is not None else 'NaN'}
weewx_wind_gust_max{period="week"} ${$w.windGust.max.raw if $w and $w.windGust and $w.windGust.max and $w.windGust.max.raw is not None else 'NaN'}
weewx_wind_gust_max{period="month"} ${$m.windGust.max.raw if $m and $m.windGust and $m.windGust.max and $m.windGust.max.raw is not None else 'NaN'}
weewx_wind_gust_max{period="year"} ${$y.windGust.max.raw if $y and $y.windGust and $y.windGust.max and $y.windGust.max.raw is not None else 'NaN'}

# ---------- Rain ----------

# HELP weewx_rain_rate_max Maximum rain rate
# TYPE weewx_rain_rate_max gauge
weewx_rain_rate_max{period="day"} ${$d.rainRate.max.raw if $d and $d.rainRate and $d.rainRate.max and $d.rainRate.max.raw is not None else 'NaN'}
weewx_rain_rate_max{period="week"} ${$w.rainRate.max.raw if $w and $w.rainRate and $w.rainRate.max and $w.rainRate.max.raw is not None else 'NaN'}
