# HELP weewx_rain_total Total rainfall
# TYPE weewx_rain_total counter
weewx_rain_total{period="day",units="${$d.rain.sum.format(' ').lstrip() if $d and $d.rain and $d.rain.sum else 'unknown'}"} ${$d.rain.sum.raw if $d and $d.rain and $d.rain.sum and $d.rain.sum.raw is not None else 'NaN'}
weewx_rain_total{period="week",units="${$w.rain.sum.format(' ').lstrip() if $w and $w.rain and $w.rain.sum else 'unknown'}"} ${$w.rain.sum.raw if $w and $w.rain and $w.rain.sum and $w.rain.sum.raw is not None else 'NaN'}
