    <script>
    function startAnimations() {
      animateText();
      setInterval(animateText, 4000);
  		startTime();
    }

    function animateText() {
      var a;
      a = document.getElementById("windBlinkerID");
      a.innerHTML = "Now: $current.windSpeed";
      setTimeout(function () {
        a.innerHTML = "Max: $span($time_delta=1800).windSpeed.max";
      }, 2000);
    }

    // add a zero in front of numbers<10
  	function leadingZero(i) {
  	  if (i < 10) {
  	    i = "0" + i;
  	  }
  	  return i;
  	}

    function startTime() {
      var now = new Date();
      var h = now.getHours();
      var m = now.getMinutes();
      //  var s = now.getSeconds();

      m = leadingZero(m);
      // s = leadingZero(s);

      var am_pm = "AM";
      if (h >= 12) {
        am_pm = "PM";
        }
      if (h >= 13) {
        h = h - 12;
        }

      // s = fixTime(s);
      document.getElementById('currentTimeID').innerHTML = h + ":" + m + " " + am_pm;
      setTimeout(function() {
        startTime()
        }, 5000);
    }

    </script>

</head>
