function ajaxforecast() {
    forecast_data = {};
    jQuery.when(
        // Get the iconlist - original source is // https://www.aerisweather.com/support/docs/api/reference/icon-list/
        jQuery.getJSON(get_relative_url() + '/images/aeris-icon-list.json', function(iconlist) {
