            // Removed the year with ", YYYY, or "/YYYY" or ".YYYY" or "-YYYY"
            if ($at_days_with_rain[1] > 0) {
                var start_day_epoch = $at_days_with_rain[1] - (($at_days_with_rain[0] - 1) * 86400);
