function getQuadraticXY(t, sx, sy, cp1x, cp1y, ex, ey) {
  return {
    x: (1-t) * (1-t) * sx + 2 * (1-t) * t * cp1x + t * t * ex,
    y: (1-t) * (1-t) * sy + 2 * (1-t) * t * cp1y + t * t * ey
  };
}


// Beaufort Wind Force Scale based on data at https://www.rmets.org/resource/beaufort-scale
function beaufort(mps) {
  kph = mps * 3.6;
  if (kph < 1)
    return 0;
  else if (kph < 6)
    return 1;
  else if (kph < 12)
    return 2;
  else if (kph < 20)
    return 3;
  else if (kph < 29)
    return 4;
  else if (kph < 38)
    return 5;
  else if (kph < 50)
    return 6;
  else if (kph < 62)
    return 7;
  else if (kph < 75)
    return 8;
  else if (kph < 89)
    return 9;
  else if (kph < 103)
    return 10;
  else if (kph < 118)
    return 11;
  else
    return 12;
}


