function belchertown_date_time_parse_formats() {
    var monthFirstFormats = [
        "MM/DD/YYYY HH:mm:ss",
        "M/D/YYYY H:mm:ss",
        "MM/DD/YYYY HH:mm",
        "M/D/YYYY H:mm",
        "MM/DD/YYYY h:mm:ss A",
        "M/D/YYYY h:mm:ss A",
        "MM/DD/YYYY h:mm A",
