        jQuery(".almanac_last_updated").text(almanac_updated);
    } catch (err) {
        // Returned "current" data does not have this value
    }
    // #end if
}

function to_radians(degrees) {
    var value = parseFloat(degrees);
    if (!isFinite(value)) {
        return null;
    }
    return value * Math.PI / 180;
}

function moon_illumination_fraction(moonData) {
    var fullness = parseFloat(moonData && moonData["moon_fullness"]);
    if (!isFinite(fullness)) {
        return null;
    }
    return Math.max(0, Math.min(1, fullness / 100));
}

function moon_tilt_template_degrees() {
    var tilt = parseFloat(moon_tilt_template_value);
    if (!isFinite(tilt)) {
        return null;
    }
    return tilt;
}

function moon_tilt_to_icon_rotation(tiltDegrees) {
    var tilt = parseFloat(tiltDegrees);
    if (!isFinite(tilt)) {
        return null;
    }

    // Skyfield moon_tilt uses the opposite sign convention from our SVG
    // screen-space rotation, so flip sign for display.
    return -tilt;
}

function moon_full_disc_path(cx, cy, r) {
    return "M " + cx + " " + (cy - r) +
        " A " + r + " " + r + " 0 1 1 " + cx + " " + (cy + r) +
        " A " + r + " " + r + " 0 1 1 " + cx + " " + (cy - r) + " Z";
}

function moon_crescent_path(cx, cy, r, rx, brightOnRight) {
    if (brightOnRight) {
        return "M " + cx + " " + (cy - r) +
            " A " + r + " " + r + " 0 0 1 " + cx + " " + (cy + r) +
            " A " + rx + " " + r + " 0 0 0 " + cx + " " + (cy - r) + " Z";
    }

    return "M " + cx + " " + (cy - r) +
        " A " + r + " " + r + " 0 0 0 " + cx + " " + (cy + r) +
        " A " + rx + " " + r + " 0 0 1 " + cx + " " + (cy - r) + " Z";
}

function moon_illuminated_path(fraction, waxing, cx, cy, r) {
    var k = Math.max(0, Math.min(1, fraction));

    if (k <= 0) {
        return "";
    }
    if (k >= 1) {
        return moon_full_disc_path(cx, cy, r);
    }

    if (k <= 0.5) {
        var rxCrescent = Math.max(0.01, r * (1 - (2 * k)));
        return moon_crescent_path(cx, cy, r, rxCrescent, waxing);
    }

    var darkPortion = 1 - k;
    var rxDark = Math.max(0.01, r * (1 - (2 * darkPortion)));
    var darkOnRight = !waxing;
    var cutoutPath = moon_crescent_path(cx, cy, r, rxDark, darkOnRight);

    // Even-odd fill creates a gibbous shape by subtracting the dark crescent.
    return moon_full_disc_path(cx, cy, r) + " " + cutoutPath;
}

function render_oriented_moon_svg(illuminationFraction, waxing, orientationDeg) {
    var cx = 20;
    var cy = 20;
    var r = 17;
    var litPath = moon_illuminated_path(illuminationFraction, waxing, cx, cy, r);
    var litFillRule = illuminationFraction > 0.5 && illuminationFraction < 1 ? "evenodd" : "nonzero";

    var isDarkTheme = jQuery("body").hasClass("dark") || sessionStorage.getItem('currentTheme') === 'dark';
    var moonDark = isDarkTheme ? "#6b7280" : "#8b95a5";
    var moonLight = isDarkTheme ? "#e5ebf7" : "#f6f8fc";
    var moonEdge = isDarkTheme ? "#cbd5e1" : "#6b7280";

    var svg = "";
    svg += "<svg class='moon-phase-svg' viewBox='0 0 40 40' width='40' height='40' aria-hidden='true' focusable='false'>";
    svg += "<g transform='rotate(" + orientationDeg.toFixed(2) + " 20 20)'>";
    svg += "<circle cx='" + cx + "' cy='" + cy + "' r='" + r + "' fill='" + moonDark + "'></circle>";
    if (litPath) {
        svg += "<path d='" + litPath + "' fill='" + moonLight + "' fill-rule='" + litFillRule + "'></path>";
    }
    svg += "<circle cx='" + cx + "' cy='" + cy + "' r='" + r + "' fill='none' stroke='" + moonEdge + "' stroke-width='0.8'></circle>";
    svg += "</g>";
    svg += "</svg>";

    return svg;
}

function render_moon_icon_html(data) {
    var almanac = data && data["almanac"];
    var moon = almanac && almanac["moon"];
    var illumination = moon_illumination_fraction(moon);
    var templateTilt = moon_tilt_template_degrees();
    var templateTiltRotation = moon_tilt_to_icon_rotation(templateTilt);
    var litDirection = 0;

    if (templateTiltRotation !== null) {
        litDirection = templateTiltRotation;
    }

    if (illumination === null || litDirection === null) {
        return moon_icon(moon && moon["moon_index"]);
    }

    // Keep shape model fixed to "bright on right", then rotate using
    // ephemeris-derived illuminated-direction angle.
    return render_oriented_moon_svg(illumination, true, litDirection);
}

//  function returns html for moon-icon according to moonphase value and currentTheme setting
function moon_icon(moonphase) {

    var moon_icon_dict = {
        "0": "<div class='wi wi-moon-new'></div>",
        "1": "<div class='wi wi-moon-waxing-crescent-3 $hemisphere'></div>",
        "2": "<div class='wi wi-moon-first-quarter $hemisphere'></div>",
        "3": "<div class='wi wi-moon-waxing-gibbous-3 $hemisphere'></div>",
        "4": "<div class='wi wi-moon-full'></div>",
        "5": "<div class='wi wi-moon-waning-gibbous-3 $hemisphere'></div>",
        "6": "<div class='wi wi-moon-third-quarter $hemisphere'></div>",
        "7": "<div class='wi wi-moon-waning-crescent-4 $hemisphere'></div>",
    }

    var output = moon_icon_dict[moonphase];
    if (sessionStorage.getItem('currentTheme') === 'dark') {
        return output;
    } else {
        return output.replace('-moon-', '-moon-alt-');
    }
}

// Forecast implementation moved to: js/new-belchertown-forecast.js.tmpl
function forecast_sync_row_height() {
    var row = document.querySelector(".forecastrow");
    if (!row) {
        return;
    }

    if (typeof forecast_fit_daily_condition_text === "function") {
        forecast_fit_daily_condition_text();
    }

    var maxHeight = 0;
    var rowWidth = row.clientWidth || row.getBoundingClientRect().width;
    ["1", "3", "24"].forEach(function(interval) {
        var panel = document.getElementById(interval + "hour-selected-forecast");
        if (!panel) {
            return;
        }

        var previous = {
            display: panel.style.display,
            left: panel.style.left,
            position: panel.style.position,
            visibility: panel.style.visibility,
            width: panel.style.width,
        };
        var isHidden = window.getComputedStyle(panel).display === "none";

        if (isHidden) {
            panel.style.display = "block";
            panel.style.left = "-9999px";
            panel.style.position = "absolute";
            panel.style.visibility = "hidden";
            panel.style.width = rowWidth + "px";
        }

        maxHeight = Math.max(maxHeight, panel.offsetHeight);

        if (isHidden) {
            panel.style.display = previous.display;
            panel.style.left = previous.left;
            panel.style.position = previous.position;
            panel.style.visibility = previous.visibility;
            panel.style.width = previous.width;
        }
    });

    if (maxHeight > 0) {
        row.style.minHeight = maxHeight + "px";
    }
}

window.addEventListener("resize", forecast_sync_row_height);

//  function to display selected forecast according to value of interval (1, 3 or 24); 0 hides all forecasts
function forecast_select(interval) {
    if (interval == 0) {
        jQuery(".forecastrow").hide();
    } else {
        forecast_sync_row_height();
        oldinterval = sessionStorage.getItem("forecastInterval");
        if (interval != oldinterval) {
            //  hide the old forecast
            var forecast = document.getElementById((oldinterval + "hour-selected-forecast"));
            var button = document.getElementById(("button" + oldinterval));
            if (forecast != null) forecast.style.display = "none";
            if (button != null) button.style.borderStyle = "hidden";
            //  display the new forecast and store its interval value
            forecast = document.getElementById((interval + "hour-selected-forecast"));
            button = document.getElementById(("button" + interval));
            if (forecast != null) forecast.style.display = "block";
            if (button != null) button.style.borderStyle = "solid";
            sessionStorage.setItem("forecastInterval", interval);
        }
        forecast_sync_row_height();
    }
}

function forecast_default(interval) {
    sessionStorage.setItem("defaultInterval", interval);
}

//  function removes weekdays from forecast_1hr & _3hr labels except at day changes
function forecast_time(i, interval, daytime, showDay) {
    if ((daytime.indexOf(" ") == -1) || (interval == "forecast_24hr")) return daytime;
    var strday = daytime.substr(0, daytime.indexOf(" "));
    var strtime = daytime.substr(daytime.indexOf(" ") + 1);

    if (interval == "forecast_1hr" || interval == "forecast_3hr") {
        if (showDay) {
            return strtime + '<br><span class="forecast-rollover-day">' + strday + '</span>';
        }
        return strtime;
    }

    return daytime;
}

