<script>
    (function() {
    function initReportsPage() {
        var params = new URLSearchParams(window.location.search);
        var month = params.get("mo");
        var year = params.get("yr");
        var url;
        if (year !== null && month !== null) {
            url = '$relative_url/noaa/NOAA-' + year + '-' + month + '.txt';
        } else if (year !== null) {
            url = '$relative_url/noaa/NOAA-' + year + '.txt';
        } else {
            url = '$relative_url/noaa/$default_noaa_file';
        }

        populatePre(url);

        // Change the direct href link
        var directLink = document.querySelector(".noaa_direct_link");
        if (directLink) {
            directLink.setAttribute("href", url);
        }

    // Change the div to the right NOAA file
    // I normally use PHP for this, but JavaScript seems to work well for the skin
    // Source: https://stackoverflow.com/a/18933218/1177153
    function populatePre(url) {
        var xhr = new XMLHttpRequest();
        xhr.onload = function() {
            var rawContent = this.responseText;
            var updatedContent = rawContent
                .replace(/<sup>/g, '')
                .replace(/<\/sup>/g, '')
                .replace(/&deg;/g, '\u00b0')
                .replace(/&amp;/g, '&')
                .replace(/&lt;/g, '<')
                .replace(/&gt;/g, '>');
            document.getElementById('noaa_contents').textContent = updatedContent;
        };
        xhr.open('GET', url);
        xhr.send();
    }

    }

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", initReportsPage);
    } else {
        initReportsPage();
    }
    })();
</script>

